 "kg": "kg",
 "<b style=\"font-size:25px;color:#8c5a2b\">Qué significa</b><br><span style=\"font-size:20px;color:#31260e\">En el ejemplo, 18 kilos de residuos al mes no llegan al contenedor.</span>": "<b style=\"font-size:25px;color:#8c5a2b\">Cosa significa</b><br><span style=\"font-size:20px;color:#31260e\">Nell'esempio, 18 chili di rifiuti al mese non finiscono nel contenitore.</span>",
 "<b style=\"font-size:25px;color:#5ba03c\">Ojo</b><br><span style=\"font-size:20px;color:#31260e\">Datos inventados para el ejemplo.</span>": "<b style=\"font-size:25px;color:#5ba03c\">Attenzione</b><br><span style=\"font-size:20px;color:#31260e\">Dati inventati per l'esempio.</span>",
